CREATE TABLE game_content_meta (
  singleton BOOLEAN PRIMARY KEY DEFAULT TRUE CHECK (singleton),
  schema_version INTEGER NOT NULL CHECK (schema_version > 0),
  content_version TEXT NOT NULL,
  seeded_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE game_characters (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  rarity SMALLINT NOT NULL CHECK (rarity BETWEEN 1 AND 5),
  description TEXT NOT NULL DEFAULT '',
  base_hp INTEGER NOT NULL, base_atk INTEGER NOT NULL, base_def INTEGER NOT NULL, base_spd INTEGER NOT NULL, base_lck INTEGER NOT NULL,
  growth_hp INTEGER NOT NULL, growth_atk INTEGER NOT NULL, growth_def INTEGER NOT NULL, growth_spd INTEGER NOT NULL, growth_lck INTEGER NOT NULL
);

CREATE TABLE game_character_skills (
  character_id TEXT NOT NULL REFERENCES game_characters(id) ON DELETE CASCADE,
  position SMALLINT NOT NULL CHECK (position >= 0),
  name TEXT NOT NULL,
  chance NUMERIC NOT NULL,
  description TEXT NOT NULL DEFAULT '',
  multiplier NUMERIC,
  ignore_def NUMERIC,
  effect_type TEXT,
  effect_stat TEXT,
  effect_value NUMERIC,
  effect_duration INTEGER,
  PRIMARY KEY (character_id, position)
);

CREATE TABLE game_equipment (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  rarity SMALLINT NOT NULL CHECK (rarity BETWEEN 1 AND 5),
  description TEXT NOT NULL DEFAULT '',
  base_hp INTEGER, base_atk INTEGER, base_def INTEGER, base_spd INTEGER, base_lck INTEGER,
  growth_hp INTEGER, growth_atk INTEGER, growth_def INTEGER, growth_spd INTEGER, growth_lck INTEGER
);

CREATE TABLE game_enemies (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  rarity SMALLINT NOT NULL CHECK (rarity BETWEEN 1 AND 5),
  hp INTEGER NOT NULL, atk INTEGER NOT NULL, def INTEGER NOT NULL, spd INTEGER NOT NULL, lck INTEGER NOT NULL
);

CREATE TABLE game_enemy_skills (
