  position SMALLINT NOT NULL CHECK (position >= 0),
  name TEXT NOT NULL,
  chance NUMERIC NOT NULL,
  multiplier NUMERIC NOT NULL,
  PRIMARY KEY (enemy_id, position)
);

CREATE TABLE game_dungeons (
  id TEXT PRIMARY KEY,
