);

CREATE TABLE game_dungeon_rewards (
  dungeon_id TEXT NOT NULL REFERENCES game_dungeons(id) ON DELETE CASCADE,
  outcome TEXT NOT NULL CHECK (outcome IN ('win', 'lose')),
  gold_min INTEGER NOT NULL CHECK (gold_min >= 0),
  gold_max INTEGER NOT NULL CHECK (gold_max >= gold_min),
  PRIMARY KEY (dungeon_id, outcome)
);

CREATE TABLE game_dungeon_character_rewards (
  dungeon_id TEXT NOT NULL REFERENCES game_dungeons(id) ON DELETE CASCADE,
