);

CREATE TABLE game_dungeon_equipment_rewards (
  dungeon_id TEXT NOT NULL REFERENCES game_dungeons(id) ON DELETE CASCADE,
  position SMALLINT NOT NULL CHECK (position >= 0),
  equipment_id TEXT NOT NULL REFERENCES game_equipment(id),
  PRIMARY KEY (dungeon_id, position),
