);

CREATE TABLE game_tower_floors (
  floor_number INTEGER PRIMARY KEY CHECK (floor_number > 0),
  id TEXT NOT NULL UNIQUE,
  name TEXT NOT NULL,
  hp INTEGER NOT NULL, atk INTEGER NOT NULL, def INTEGER NOT NULL, spd INTEGER NOT NULL, lck INTEGER NOT NULL
);

CREATE TABLE game_tower_skills (
  floor_number INTEGER NOT NULL REFERENCES game_tower_floors(floor_number) ON DELETE CASCADE,
  position SMALLINT NOT NULL CHECK (position >= 0),
  name TEXT NOT NULL,
  chance NUMERIC NOT NULL,
  multiplier NUMERIC NOT NULL,
  PRIMARY KEY (floor_number, position)
);

CREATE TABLE game_tower_reward_bands (
  min_floor INTEGER PRIMARY KEY CHECK (min_floor > 0),
  max_floor INTEGER NOT NULL CHECK (max_floor >= min_floor),
  gold INTEGER NOT NULL CHECK (gold >= 0),
  gold_rate NUMERIC NOT NULL CHECK (gold_rate BETWEEN 0 AND 1),
  soul_min INTEGER NOT NULL CHECK (soul_min >= 0),
  soul_max INTEGER NOT NULL CHECK (soul_max >= soul_min),
  soul_rate NUMERIC NOT NULL CHECK (soul_rate BETWEEN 0 AND 1),
  iron_min INTEGER NOT NULL CHECK (iron_min >= 0),
  iron_max INTEGER NOT NULL CHECK (iron_max >= iron_min),
  iron_rate NUMERIC NOT NULL CHECK (iron_rate BETWEEN 0 AND 1),
  UNIQUE (max_floor)
);

CREATE TABLE game_quest_chapters (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  description TEXT NOT NULL DEFAULT '',
