);

CREATE TABLE game_quests (
  id TEXT PRIMARY KEY,
  chapter_id TEXT NOT NULL REFERENCES game_quest_chapters(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  description TEXT NOT NULL,
  display_order SMALLINT NOT NULL CHECK (display_order > 0),
